sys_variable_value.value:
(function() {
    // PulseScore Recalculation Script
    // Runs every 15 minutes to calculate composite health scores for Dark Stores

    var WEIGHT_COMPLAINTS = 0.25;
    var WEIGHT_REFUNDS = 0.20;
    var WEIGHT_SLA = 0.20;
    var WEIGHT_EQUIPMENT = 0.15;
    var WEIGHT_PARTNER_INCIDENTS = 0.20;

    var GREEN_THRESHOLD = 80;
    var YELLOW_THRESHOLD = 50;

    gs.info('PulseScore Recalculation: Starting calculation cycle');

    // Query all active Dark Store records
    var stores = new GlideRecord('x_2145749_qc_dark_store');
    stores.addQuery('status', 'active');
    stores.query();

    while (stores.next()) {
        var storeSysId = stores.getUniqueValue();
        var storeName = stores.getValue('store_name');
        var zoneSysId = stores.getValue('zone');
        var previousBand = stores.getValue('pulse_score_band') || '';

        try {
            // Calculate trailing 24-hour window
            var twentyFourHoursAgo = new GlideDateTime();
            twentyFourHoursAgo.addSeconds(-86400);
            var windowStart = twentyFourHoursAgo.getValue();

            // Signal 1: Complaint Volume (from sn_customerservice_case)
            var complaints = new GlideRecord('sn_customerservice_case');
            complaints.addQuery('x_2145749_qc_dark_store', storeSysId);
            complaints.addQuery('sys_created_on', '>=', windowStart);
            complaints.query();
            var complaintCount = complaints.getRowCount();
            // Score: 100 if 0 complaints, decreases by 10 per complaint, min 0
            var complaintScore = Math.max(0, 100 - (complaintCount * 10));

            // Signal 2: Refund Rate (from x_2145749_qc_refund_request via case.dark_store)
            var refunds = new GlideRecord('x_2145749_qc_refund_request');
            refunds.addQuery('case.x_2145749_qc_dark_store', storeSysId);
            refunds.addQuery('sys_created_on', '>=', windowStart);
            refunds.query();
            var refundCount = refunds.getRowCount();
            // Score: 100 if 0 refunds, decreases by 15 per refund, min 0
            var refundScore = Math.max(0, 100 - (refundCount * 15));

            // Signal 3: SLA Breach Count (from task_sla for cases tied to this store)
            var slaCases = new GlideRecord('sn_customerservice_case');
            slaCases.addQuery('x_2145749_qc_dark_store', storeSysId);
            slaCases.addQuery('sys_created_on', '>=', windowStart);
            slaCases.query();
            var slaBreachCount = 0;
            while (slaCases.next()) {
                var taskSla = new GlideRecord('task_sla');
                taskSla.addQuery('task', slaCases.getUniqueValue());
                taskSla.addQuery('has_breached', 'true');
                taskSla.query();
                slaBreachCount += taskSla.getRowCount();
            }
            // Score: 100 if 0 breaches, decreases by 20 per breach, min 0
            var slaScore = Math.max(0, 100 - (slaBreachCount * 20));

            // Signal 4: Equipment Downtime (from x_2145749_qc_equipment)
            var totalEquipment = new GlideRecord('x_2145749_qc_equipment');
            totalEquipment.addQuery('dark_store', storeSysId);
            totalEquipment.query();
            var totalEquipCount = totalEquipment.getRowCount();

            var downEquipment = new GlideRecord('x_2145749_qc_equipment');
            downEquipment.addQuery('dark_store', storeSysId);
            downEquipment.addQuery('operational_status', '!=', 'operational');
            downEquipment.query();
            var downCount = downEquipment.getRowCount();

            var equipmentScore = 100;
            if (totalEquipCount > 0) {
                equipmentScore = Math.round(((totalEquipCount - downCount) / totalEquipCount) * 100);
            }

            // Signal 5: Delivery Partner Incident Count
            var partnerIncidents = new GlideRecord('x_2145749_qc_partner_incident');
            partnerIncidents.addQuery('dark_store', storeSysId);
            partnerIncidents.addQuery('sys_created_on', '>=', windowStart);
            partnerIncidents.query();
            var partnerIncidentCount = partnerIncidents.getRowCount();
            // Score: 100 if 0 incidents, decreases by 12 per incident, min 0
            var partnerIncidentScore = Math.max(0, 100 - (partnerIncidentCount * 12));

            // Calculate composite score (0-100)
            var compositeScore = Math.round(
                (complaintScore * WEIGHT_COMPLAINTS) +
                (refundScore * WEIGHT_REFUNDS) +
                (slaScore * WEIGHT_SLA) +
                (equipmentScore * WEIGHT_EQUIPMENT) +
                (partnerIncidentScore * WEIGHT_PARTNER_INCIDENTS)
            );

            // Determine band
            var band = 'red';
            if (compositeScore >= GREEN_THRESHOLD) {
                band = 'green';
            } else if (compositeScore >= YELLOW_THRESHOLD) {
                band = 'yellow';
            }

            // Insert new PulseScore snapshot (never overwrite, always insert new)
            var snapshot = new GlideRecord('x_2145749_qc_pulse_score');
            snapshot.initialize();
            snapshot.setValue('dark_store', storeSysId);
            snapshot.setValue('score', compositeScore);
            snapshot.setValue('band', band);
            snapshot.setValue('snapshot_time', new GlideDateTime().getValue());
            snapshot.setValue('complaint_volume_score', complaintScore);
            snapshot.setValue('partner_incident_score', partnerIncidentScore);
            snapshot.setValue('equipment_uptime_score', equipmentScore);
            snapshot.setValue('sla_compliance_score', slaScore);
            snapshot.setValue('refund_fraud_score', refundScore);
            snapshot.setValue('open_complaint_count', complaintCount);
            if (zoneSysId) {
                snapshot.setValue('zone', zoneSysId);
            }
            snapshot.insert();

            // Update the Dark Store record
            stores.setValue('pulse_score', compositeScore);
            stores.setValue('pulse_score_band', band);
            stores.update();

            // Check for band transition to Red
            if (band === 'red' && previousBand !== 'red' && previousBand !== '') {
                gs.info('PulseScore Recalculation: Store ' + storeName + ' transitioned to RED band (score: ' + compositeScore + '). Sending notification.');

                // Notify ops_leadership role group
                gs.eventQueue('x_2145749_qc.pulse_score_red_alert', stores,
                    'Store: ' + storeName + ', Score: ' + compositeScore + ', Band: RED',
                    'x_2145749_qc.ops_leadership');

                // Notify the store manager
                var managerSysId = stores.getValue('manager');
                if (managerSysId) {
                    var manager = new GlideRecord('sys_user');
                    if (manager.get(managerSysId)) {
                        gs.eventQueue('x_2145749_qc.pulse_score_red_alert', stores,
                            'Store: ' + storeName + ', Score: ' + compositeScore + ', Band: RED',
                            manager.getValue('email'));
                    }
                }
            }

            gs.info('PulseScore Recalculation: Store ' + storeName + ' - Score: ' + compositeScore + ', Band: ' + band +
                ' (Complaints: ' + complaintScore + ', Refunds: ' + refundScore +
                ', SLA: ' + slaScore + ', Equipment: ' + equipmentScore +
                ', Partner Incidents: ' + partnerIncidentScore + ')');

        } catch (e) {
            // Error handling: keep prior score unchanged, log error
            gs.error('PulseScore Recalculation: Error calculating score for store ' + storeName + ': ' + e.message + '. Keeping prior score unchanged.');
        }
    }

    gs.info('PulseScore Recalculation: Calculation cycle complete');
})();

